var i=`rate-limiting-and-throttling`;var s=67;var n={en:[{id:`T067-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Rate Limiting & Throttling`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Webhooks deliver events via outbound HTTP calls; message queues broker asynchronous delivery between producers and consumers.`},{id:`B`,text:`Remote Procedure Call presents network operations as service methods; gRPC commonly uses Protocol Buffers, HTTP/2 and generated contracts.`},{id:`C`,text:`Rate limiting constrains request frequency or cost; throttling delays or rejects traffic to protect capacity and fairness.`},{id:`D`,text:`Authentication establishes who or what is making a request; authorization determines what that principal may do.`}]},{id:`T067-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Rate Limiting & Throttling`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Choose a key such as user, tenant, IP or API token, and budget based on endpoint cost.`},{id:`B`,text:`Offset pagination is simple but can degrade at large offsets and shift under concurrent inserts.`},{id:`C`,text:`Prefer additive contracts, optional fields with sensible defaults, tolerant readers within documented bounds, and explicit deprecation policies.`},{id:`D`,text:`Check token/session validity, then evaluate permissions against action, resource and context.`}]},{id:`T067-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Rate Limiting & Throttling`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A mobile app signs in via an OIDC provider and receives identity claims, then calls a hotel API with an audience-scoped access token. The backend still authorizes each booking.`},{id:`B`,text:`A payment provider sends a signed charge-success webhook. The receiver verifies authenticity, stores the event ID, acknowledges quickly and processes the state change asynchronously once.`},{id:`C`,text:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`},{id:`D`,text:`An infinite activity feed uses a cursor based on timestamp and unique ID. A sortable admin grid might choose offset pages for ease of jumping to a specific position.`}]},{id:`T067-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Rate Limiting & Throttling`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Webhook endpoints are exposed to forged requests, slow handlers and SSRF-like delivery misconfiguration.`},{id:`B`,text:`Versioning cannot compensate for undocumented behavior.`},{id:`C`,text:`GraphQL does not automatically solve backend performance; arbitrary client queries can be expensive.`},{id:`D`,text:`IP-only limits punish users behind shared NAT and may miss distributed attackers.`}]},{id:`T067-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Algorithms include token bucket, leaky bucket, fixed window and sliding window.`}]}]},{id:`T067-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A single global request limit is always sufficient for every API endpoint.`}]}]},{id:`T067-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A limit without admission queues, monitoring or client backoff can create retry storms.`}]}]},{id:`T067-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Rate Limiting & Throttling`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Choose a key such as user, tenant, IP or API token, and budget based on endpoint cost.`},{id:`B`,text:`A rate limit that returns 429 never needs a retry policy or headers.`},{id:`C`,text:`Rate limiting constrains request frequency or cost; throttling delays or rejects traffic to protect capacity and fairness.`},{id:`D`,text:`gRPC always works without adaptation in every browser environment.`}]},{id:`T067-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Rate Limiting & Throttling`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A single global request limit is always sufficient for every API endpoint.`},{id:`B`,text:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`},{id:`C`,text:`Cursor pagination guarantees consistent ordering even when the sort key is not stable.`},{id:`D`,text:`A limit without admission queues, monitoring or client backoff can create retry storms.`}]},{id:`T067-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to classify a list of schema changes as additive or breaking and produce a rollout plan with compatibility tests for old mobile clients.`},{id:`B`,text:`Ask an agent to design a distributed token-bucket limiter with tenant fairness, burst behavior, 429 responses and metrics for legitimate versus abusive traffic.`},{id:`C`,text:`Ask an agent to design signed inbound webhooks and an internal queue with deduplication, quick acknowledgment, retries and replay-safe processing.`},{id:`D`,text:`Have an agent design a typed booking schema with batching, complexity limits and field authorization. Test nested query abuse and unauthorized field access.`}]},{id:`T067-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How should limits differ between an inexpensive read and an expensive report generation?`}]}]},{id:`T067-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Rate Limiting & Throttling`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T067-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`,b:!0},{t:` — propose three checks for `},{t:`Rate Limiting & Throttling`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T067-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T067-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Rate Limiting & Throttling`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T067-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Webhook передає події вихідним HTTP-запитом; черга повідомлень доставляє асинхронні задачі між виробником і споживачем.`},{id:`B`,text:`RPC представляє мережеві операції як методи сервісу; gRPC часто використовує Protocol Buffers, HTTP/2 і згенеровані контракти.`},{id:`C`,text:`Rate limiting обмежує частоту або вартість запитів; throttling затримує чи відхиляє трафік, щоб захистити ресурси та справедливість.`},{id:`D`,text:`Автентифікація встановлює особу або сервіс, що робить запит; авторизація визначає дозволені дії.`}]},{id:`T067-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Оберіть ключ за користувачем, tenant, IP або токеном і ліміт за ціною endpoint.`},{id:`B`,text:`Offset-пагінація проста, але повільніша на великих зміщеннях і зміщується при нових записах.`},{id:`C`,text:`Віддавайте перевагу додаванню полів, необов’язковим значенням із розумними defaults, читачам, які терплять документовану варіативність, і явним правилам deprecation.`},{id:`D`,text:`Перевіряйте токен або сесію, потім оцінюйте дозвіл з огляду на дію, ресурс і контекст.`}]},{id:`T067-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Мобільний застосунок входить через OIDC-провайдера й отримує identity claims, а API готелю викликає access token із правильною audience. Бекенд усе одно перевіряє право на бронювання.`},{id:`B`,text:`Платіжний провайдер надсилає підписаний webhook про оплату. Приймач перевіряє автентичність, зберігає ID, швидко підтверджує прийом і асинхронно обробляє зміну стану.`},{id:`C`,text:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`},{id:`D`,text:`Нескінченна стрічка активності використовує cursor за timestamp та унікальним ID. Адміністративна таблиця може залишити offset для переходу на конкретну сторінку.`}]},{id:`T067-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Webhook endpoints ризикують підробленими запитами, повільною обробкою й помилками налаштування адрес доставки.`},{id:`B`,text:`Версіонування не виправляє недокументованої поведінки.`},{id:`C`,text:`GraphQL не прискорює бекенд автоматично: довільні запити можуть бути дорогими.`},{id:`D`,text:`Ліміт лише за IP карає користувачів за спільним NAT і пропускає розподілені атаки.`}]},{id:`T067-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Алгоритми: token bucket, leaky bucket, fixed і sliding window.`}]}]},{id:`T067-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Одного глобального ліміту запитів завжди достатньо для всіх endpoint API.`}]}]},{id:`T067-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Без черг, моніторингу та backoff можна створити лавину повторів.`}]}]},{id:`T067-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Оберіть ключ за користувачем, tenant, IP або токеном і ліміт за ціною endpoint.`},{id:`B`,text:`Ліміт із відповіддю 429 ніколи не потребує політики повторів чи заголовків.`},{id:`C`,text:`Rate limiting обмежує частоту або вартість запитів; throttling затримує чи відхиляє трафік, щоб захистити ресурси та справедливість.`},{id:`D`,text:`gRPC завжди без адаптації працює в будь-якому браузері.`}]},{id:`T067-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Одного глобального ліміту запитів завжди достатньо для всіх endpoint API.`},{id:`B`,text:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`},{id:`C`,text:`Cursor-пагінація гарантує порядок навіть із нестабільним ключем сортування.`},{id:`D`,text:`Без черг, моніторингу та backoff можна створити лавину повторів.`}]},{id:`T067-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента розділити зміни схеми на сумісні й несумісні та створити план релізу з тестами старих мобільних клієнтів.`},{id:`B`,text:`Попросіть агента спроєктувати розподілений token bucket із справедливістю між tenant, підтримкою burst, 429 і метриками легального та зловмисного трафіку.`},{id:`C`,text:`Попросіть агента спроєктувати підписані вхідні webhook і внутрішню чергу з дедуплікацією, швидким ACK, повторами й захистом від replay.`},{id:`D`,text:`Попросіть агента створити типізовану схему бронювань з batching, лімітами складності та авторизацією полів. Перевірте глибокі запити й несанкціонований доступ.`}]},{id:`T067-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Чим мають відрізнятися ліміти дешевого читання й дорогого формування звіту?`}]}]},{id:`T067-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T067-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T067-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T067-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Обмеження частоти та регулювання навантаження`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:67,questions:n};export{o as default,n as questions,i as slug,s as topicId};